import { useThreadStore } from '../store/threadStore'
import {
	GetProjectGroupRevisionsForChatDocument,
	GetThreadsForProjectGroupDocument,
	type GetThreadsForProjectGroupQuery,
	type GetThreadsForProjectGroupQueryVariables,
	type GetProjectGroupRevisionsForChatQuery,
	type GetProjectGroupRevisionsForChatQueryVariables,
	type ProjectGroupRevisionForChatFragment
} from '@/generated/graphql'
import type { ApolloCache } from '@apollo/client/cache'
import { setRevisionIdForClientId } from './chat-message-map'
import { MESSAGES_PER_PAGE } from '@/constants'
type Args = {
	clientId: string
	projectGroupId: string
	cache: ApolloCache<unknown>
	revision: ProjectGroupRevisionForChatFragment
	threadId: string | null
	isNewProjectGroup: boolean
}
const addRevisionForChat = ({
	cache,
	revision,
	projectGroupId,
	threadId,
	isNewProjectGroup
}: Args) => {
	if (!projectGroupId) return
	const newRevision = {
		...revision,
		__typename: 'ProjectGroupRevision' as const
	}

	if (isNewProjectGroup) {
		cache.writeQuery<
			GetProjectGroupRevisionsForChatQuery,
			GetProjectGroupRevisionsForChatQueryVariables
		>({
			query: GetProjectGroupRevisionsForChatDocument,
			data: {
				projectGroupById: {
					__typename: 'ProjectGroup',
					id: projectGroupId,
					latestRevision: newRevision,
					revisions: {
						__typename: 'ProjectGroupRevisionConnection',
						totalCount: 1,
						pageInfo: {
							__typename: 'PageInfo',
							hasNextPage: false,
							hasPreviousPage: false,
							endCursor: null,
							startCursor: null
						},
						edges: [
							{
								__typename: 'ProjectGroupRevisionEdge',
								node: newRevision
							}
						]
					}
				}
			},
			variables: {
				projectGroupId,
				threadId,
				first: MESSAGES_PER_PAGE
			}
		})
		return
	}
	const result = cache.readQuery<
		GetProjectGroupRevisionsForChatQuery,
		GetProjectGroupRevisionsForChatQueryVariables
	>({
		query: GetProjectGroupRevisionsForChatDocument,
		variables: {
			projectGroupId,
			threadId,
			first: MESSAGES_PER_PAGE
		}
	})

	if (!result) {
		return
	}
	cache.writeQuery<
		GetProjectGroupRevisionsForChatQuery,
		GetProjectGroupRevisionsForChatQueryVariables
	>({
		query: GetProjectGroupRevisionsForChatDocument,
		data: {
			projectGroupById: {
				...result.projectGroupById,
				latestRevision: newRevision,
				revisions: {
					...result.projectGroupById.revisions,
					edges: [
						{
							__typename: 'ProjectGroupRevisionEdge',
							node: newRevision
						},
						...result.projectGroupById.revisions.edges.filter(
							(edge) => edge.node.id !== newRevision.id
						)
					]
				}
			}
		},
		variables: {
			projectGroupId,
			threadId,
			first: MESSAGES_PER_PAGE
		}
	})
}

const moveThreadToFront = ({ cache, projectGroupId, threadId }: Args) => {
	if (!projectGroupId) return
	const existingThreads = cache.readQuery<
		GetThreadsForProjectGroupQuery,
		GetThreadsForProjectGroupQueryVariables
	>({
		query: GetThreadsForProjectGroupDocument,
		variables: { input: { projectGroupId }, projectGroupId }
	})
	if (!threadId) {
		useThreadStore.getState().setEmptyThreadUpdatedAt(new Date())
		return
	}
	if (existingThreads) {
		cache.writeQuery<
			GetThreadsForProjectGroupQuery,
			GetThreadsForProjectGroupQueryVariables
		>({
			query: GetThreadsForProjectGroupDocument,
			variables: { input: { projectGroupId }, projectGroupId },
			data: {
				projectGroupById: {
					...existingThreads.projectGroupById,
					latestThread:
						existingThreads.projectGroupRevisionThreadsByProjectGroupId.edges.find(
							(edge) => edge.node.id === threadId
						)?.node || existingThreads.projectGroupById.latestThread
				},
				projectGroupRevisionThreadsByProjectGroupId: {
					__typename: 'ProjectGroupRevisionThreadConnection',
					pageInfo:
						existingThreads.projectGroupRevisionThreadsByProjectGroupId
							.pageInfo,
					edges:
						// Move the thread with threadId to the front
						existingThreads.projectGroupRevisionThreadsByProjectGroupId.edges.map(
							(a) => ({
								...a,
								node:
									a.node.id === threadId
										? {
												...a.node,
												updatedAt: new Date().toISOString()
										  }
										: a.node
							})
						)
				}
			}
		})
	}
}

export const addRevisionForChatToApolloCache = ({
	cache,
	revision,
	projectGroupId,
	clientId,
	threadId,
	isNewProjectGroup
}: Args) => {
	setRevisionIdForClientId({
		clientId,
		revisionId: revision.id
	})
	addRevisionForChat({
		cache,
		revision,
		projectGroupId,
		clientId,
		threadId,
		isNewProjectGroup
	})
	moveThreadToFront({
		cache,
		projectGroupId,
		threadId,
		clientId,
		revision,
		isNewProjectGroup
	})
}

export const addThreadToApolloCache = ({
	cache,
	projectGroupId,
	thread
}: {
	cache: ApolloCache<unknown>
	projectGroupId: string
	thread: GetThreadsForProjectGroupQuery['projectGroupRevisionThreadsByProjectGroupId']['edges'][0]['node']
}) => {
	if (!projectGroupId) return
	const existingThreads = cache.readQuery<
		GetThreadsForProjectGroupQuery,
		GetThreadsForProjectGroupQueryVariables
	>({
		query: GetThreadsForProjectGroupDocument,
		variables: { input: { projectGroupId }, projectGroupId }
	})
	if (existingThreads) {
		cache.writeQuery<
			GetThreadsForProjectGroupQuery,
			GetThreadsForProjectGroupQueryVariables
		>({
			query: GetThreadsForProjectGroupDocument,
			variables: { input: { projectGroupId }, projectGroupId },
			data: {
				projectGroupById: {
					...existingThreads.projectGroupById,
					latestThread: thread
				},
				projectGroupRevisionThreadsByProjectGroupId: {
					__typename: 'ProjectGroupRevisionThreadConnection',
					pageInfo:
						existingThreads.projectGroupRevisionThreadsByProjectGroupId
							.pageInfo,
					edges: [
						{
							__typename: 'ProjectGroupRevisionThreadEdge',
							node: thread
						},
						...existingThreads.projectGroupRevisionThreadsByProjectGroupId.edges.filter(
							(edge) => edge.node.id !== thread.id
						)
					]
				}
			}
		})
	} else {
		// if no existing threads, we need to write the query
		cache.writeQuery<
			GetThreadsForProjectGroupQuery,
			GetThreadsForProjectGroupQueryVariables
		>({
			query: GetThreadsForProjectGroupDocument,
			variables: { input: { projectGroupId }, projectGroupId },
			data: {
				projectGroupById: {
					__typename: 'ProjectGroup',
					id: projectGroupId,
					latestThread: thread
				},
				projectGroupRevisionThreadsByProjectGroupId: {
					__typename: 'ProjectGroupRevisionThreadConnection',
					pageInfo: {
						__typename: 'PageInfo',
						hasNextPage: false,
						endCursor: null
					},
					edges: [
						{
							__typename: 'ProjectGroupRevisionThreadEdge',
							node: thread
						}
					]
				}
			}
		})
	}
}
